import assert from 'node:assert/strict';
import fs from 'node:fs';
import * as authoring from '../../../../packages/rpgmaker-event-dsl/src/index.ts';
import { renderMovementRoute } from '../../../../packages/rpgmaker-event-dsl/src/commands/movement/decompile.ts';
import { compileMovementRoute } from '../../../../packages/rpgmaker-event-dsl/src/commands/movement/compile.ts';

// Codes independently inventoried from shipped Game_Character.ROUTE_* constants.
// Parameter examples are bounded by shipped editor controls, not generated by product code.
const parameters: Record<number, unknown[]> = {
  14: [-99, 99], 15: [1], 27: [1], 28: [1], 29: [1], 30: [1],
  41: ['', 0], 42: [0], 43: [0],
  44: [{name:'',volume:90,pitch:100,pan:0}], 45: ['\r\n// literal CRLF\n'],
};
const entries = Object.entries(authoring);
const names = entries.map(([k])=>k);
const values = entries.map(([,v])=>v);
const resolver = { resolveReference: (reference: {id?:number}) => reference.id??1 };
const result: unknown[] = [];
for (let code = 1; code <= 45; code++) {
  for (const indent of ['absent','null','zero'] as const) {
    for (const terminal of ['absent','empty'] as const) {
      const command = {code,...(parameters[code]?{parameters:parameters[code]}:{}),
        ...(indent==='null'?{indent:null}:indent==='zero'?{indent:0}:{})};
      const route = {list:[command,terminal==='empty'?{code:0,parameters:[]}:{code:0}],
        repeat:false,skippable:true,wait:true};
      try {
        const rendered = renderMovementRoute(route)!;
        assert.ok(rendered);
        assert.ok(!rendered.expression.includes('rawDslCommand'));
        const dsl = Function(...names, `return (${rendered.expression})`)(...values);
        const compiled = compileMovementRoute(dsl,resolver as never);
        assert.deepStrictEqual(compiled,route);
        result.push({code,indent,terminal,passed:true});
      } catch(error) {
        result.push({code,indent,terminal,passed:false,error:String(error)});
      }
    }
  }
}
const report = { scope:'45 independently inventoried movement codes × 3 finite indent shapes × 2 M0 parameter shapes; module-level data round trip only',passed:result.filter((r:any)=>r.passed).length,total:result.length,failed:result.filter((r:any)=>!r.passed)};
fs.writeFileSync(new URL('./movement-roundtrip.json',import.meta.url),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report,null,2));
assert.equal(report.passed,report.total);
